-- Phase 3, M1: attendance core.
--
-- Plan and the decisions behind every table here:
-- docs/phase-notes/phase-3-attendance-plan.md
--
-- Hand-written rather than generated by `migrate dev`, for the same reason as
-- every migration before it: this project connects through Neon's pooled
-- endpoint, where Prisma cannot build the shadow database its drift detection
-- needs. The table and index statements below are exactly what
-- `prisma migrate diff --from-config-datasource --to-schema` produced; the
-- sections marked HAND-WRITTEN are what the schema language cannot express.
-- Apply with `prisma migrate deploy`.
--
-- Purely additive and safe against existing rows:
--
--  * Organization.timezone is NOT NULL DEFAULT 'Africa/Lagos', so every
--    existing organisation gets Lagos with no backfill.
--  * Office.workRuleId is nullable: null means "the organisation's default
--    rule", and no organisation has one yet.
--  * Four new tables, all empty.
--
-- No default WorkRule is created for existing organisations. Inventing 08:00
-- to 17:00 for a company that never said so would make the first lateness
-- report wrong for them. Until a rule exists, nobody is late and nobody is
-- absent — the honest answer when nothing has been configured.

-- CreateEnum
CREATE TYPE "HolidayType" AS ENUM ('PUBLIC', 'COMPANY');

-- CreateEnum
CREATE TYPE "PunchType" AS ENUM ('CLOCK_IN', 'CLOCK_OUT', 'BREAK_START', 'BREAK_END');

-- CreateEnum
CREATE TYPE "AttendanceStatus" AS ENUM ('PRESENT', 'ABSENT', 'ON_HOLIDAY', 'REST_DAY');

-- AlterTable
ALTER TABLE "Office" ADD COLUMN     "workRuleId" TEXT;

-- AlterTable
ALTER TABLE "Organization" ADD COLUMN     "timezone" TEXT NOT NULL DEFAULT 'Africa/Lagos';

-- CreateTable
CREATE TABLE "WorkRule" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "isDefault" BOOLEAN NOT NULL DEFAULT false,
    "workingDays" INTEGER[],
    "startMinutes" INTEGER NOT NULL,
    "endMinutes" INTEGER NOT NULL,
    "gracePeriodMinutes" INTEGER NOT NULL DEFAULT 0,
    "overtimeAfterMinutes" INTEGER,
    "overtimeMultiplier" DECIMAL(4,2) NOT NULL DEFAULT 1.5,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "WorkRule_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "Holiday" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "date" DATE NOT NULL,
    "type" "HolidayType" NOT NULL DEFAULT 'PUBLIC',
    "repeatsAnnually" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Holiday_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "PunchEvent" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "type" "PunchType" NOT NULL,
    "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "workDate" DATE NOT NULL,
    "latitude" DOUBLE PRECISION,
    "longitude" DOUBLE PRECISION,
    "accuracyMeters" DOUBLE PRECISION,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "PunchEvent_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "AttendanceSummary" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "workDate" DATE NOT NULL,
    "status" "AttendanceStatus" NOT NULL,
    "firstClockIn" TIMESTAMP(3),
    "lastClockOut" TIMESTAMP(3),
    "workedMinutes" INTEGER NOT NULL DEFAULT 0,
    "breakMinutes" INTEGER NOT NULL DEFAULT 0,
    "overtimeMinutes" INTEGER NOT NULL DEFAULT 0,
    "isLate" BOOLEAN NOT NULL DEFAULT false,
    "lateMinutes" INTEGER NOT NULL DEFAULT 0,
    "isIncomplete" BOOLEAN NOT NULL DEFAULT false,
    "workRuleId" TEXT,
    "scheduledStartMinutes" INTEGER,
    "scheduledEndMinutes" INTEGER,
    "gracePeriodMinutes" INTEGER,
    "computedAt" TIMESTAMP(3) NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "AttendanceSummary_pkey" PRIMARY KEY ("id")
);

