ALTER TABLE "PunchEvent" ADD CONSTRAINT "PunchEvent_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

