ALTER TABLE "AttendanceSummary" ADD CONSTRAINT "AttendanceSummary_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

