ALTER TABLE "AttendanceSummary" ADD CONSTRAINT "AttendanceSummary_workRuleId_fkey" FOREIGN KEY ("workRuleId") REFERENCES "WorkRule"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- ─── HAND-WRITTEN 1: exactly one default rule per organisation ─────────────
--
-- A partial unique index: at most one row per organisation may have
-- isDefault = true. Prisma cannot express a partial index, so this exists only
-- here — `migrate diff` will not report it as drift and will not recreate it
-- if dropped. Switching the default is two statements (clear the old, set the
-- new) inside one transaction; the reverse order violates this.

CREATE UNIQUE INDEX "WorkRule_one_default_per_org"
  ON "WorkRule" ("organizationId")
  WHERE "isDefault";


-- ─── HAND-WRITTEN 2: a work rule that makes sense ──────────────────────────
--
-- These are the invariants the summary arithmetic assumes. Enforcing them here
-- means a bad rule is refused when it is saved, not discovered as a negative
-- lateness figure on someone's payslip.
--
-- end > start is Phase 3 decision 5: no overnight shifts in the MVP. Lifting it
-- is a deliberate change to this constraint, never a data edit around it.
--
-- workingDays NOT NULL is a CHECK rather than a column constraint: Prisma
-- generates scalar lists as nullable, and changing the column would show as
-- drift on every later `migrate diff`.

ALTER TABLE "WorkRule"
  ADD CONSTRAINT "WorkRule_minutes_in_day"
    CHECK ("startMinutes" >= 0 AND "endMinutes" <= 1440),
  ADD CONSTRAINT "WorkRule_end_after_start"
    CHECK ("endMinutes" > "startMinutes"),
  ADD CONSTRAINT "WorkRule_grace_range"
    CHECK ("gracePeriodMinutes" BETWEEN 0 AND 180),
  ADD CONSTRAINT "WorkRule_overtime_after_nonnegative"
    CHECK ("overtimeAfterMinutes" IS NULL OR "overtimeAfterMinutes" >= 0),
  ADD CONSTRAINT "WorkRule_overtime_multiplier_range"
    CHECK ("overtimeMultiplier" >= 1 AND "overtimeMultiplier" <= 5),
  ADD CONSTRAINT "WorkRule_working_days_valid"
    CHECK (
      "workingDays" IS NOT NULL
      AND cardinality("workingDays") BETWEEN 1 AND 7
      AND "workingDays" <@ ARRAY[1, 2, 3, 4, 5, 6, 7]
    );


-- ─── HAND-WRITTEN 3: punches are append-only ───────────────────────────────
--
-- PRTS §12: "Punch Events are immutable." Enforced by the database so the
-- guarantee does not depend on nobody ever writing an update route. Any UPDATE
-- or DELETE raises, from the application, from a migration, or from someone
-- with a SQL console.
--
-- TRUNCATE is deliberately not blocked: row-level triggers do not fire on it,
-- and the e2e suite resets tables with TRUNCATE between specs. Nothing in the
-- application truncates.
--
-- The user and organisation foreign keys are ON DELETE RESTRICT, so this
-- trigger is never what stops a cascade — the cascade cannot start.

CREATE FUNCTION "punch_event_is_append_only"() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'PunchEvent rows are append-only: % is not allowed (record a new punch instead)', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "PunchEvent_append_only"
  BEFORE UPDATE OR DELETE ON "PunchEvent"
  FOR EACH ROW EXECUTE FUNCTION "punch_event_is_append_only"();


-- ─── HAND-WRITTEN 4: summary figures cannot go negative ────────────────────
--
-- A negative duration means the arithmetic is wrong. Refuse the write so the
-- bug surfaces as an error in testing rather than as a quiet deduction.

ALTER TABLE "AttendanceSummary"
  ADD CONSTRAINT "AttendanceSummary_durations_nonnegative"
    CHECK (
      "workedMinutes" >= 0 AND "breakMinutes" >= 0
      AND "overtimeMinutes" >= 0 AND "lateMinutes" >= 0
    ),
  ADD CONSTRAINT "AttendanceSummary_late_consistent"
    CHECK ("isLate" = ("lateMinutes" > 0));
